      Bf.morale = (Bf.morale == null ? 70 : Bf.morale) - 5 * (total(b) / (s0b + 1) < total(a) / (s0a + 1) ? 2 : 0.5);
      log.push('제' + r + '합 — ' + A.name + ' ' + total(a).toLocaleString() + ' / ' + B.name + ' ' + total(b).toLocaleString());
