window.__sgL=21;
/* 확장 사건 묶음 ⑤ — 삼국 시대 실제 일화(평강공주·이차돈·우산국 정벌·박제상·황산벌·살수 유인 등)와 고전 사례를 본뜬 사건.
 * 실제 일화는 사건의 줄거리만 빌려 왔고 선택과 결과는 창작이다. 시대(연도)와 정세에 맞는 조건을 걸었다.
 * 번역은 events6.js 와 같은 방식(T)으로 SG.data.tr6 에 모은다. T()는 반드시 파일을 읽을 때(함수 밖에서) 부른다.
 * 표기 규칙: 한국어 문장 안에 작은따옴표를 쓰지 않는다. */
window.SG = window.SG || {}; SG.data = SG.data || {};
(function () {
  var TR = SG.data.tr6 = SG.data.tr6 || { en: {}, ja: {} };
  function T(k, e, j) { TR.en[k] = e; TR.ja[k] = j; return k; }
  function C(l, h, r, o) { var c = o || {}; c.label = T(l[0], l[1], l[2]); if (h) c.hint = T(h[0], h[1], h[2]); if (r) c.result = T(r[0], r[1], r[2]); return c; }
  function R(p, a, b) { a.text = T(a.t[0], a.t[1], a.t[2]); b.text = T(b.t[0], b.t[1], b.t[2]); return function (S) { return S.roll() < p ? a : b; }; }
  function EV(id, title, cat, w, hist, cond, text, choices) {
    var tt = T(title[0], title[1], title[2]), tx = T(text[0], text[1], text[2]);
    return { id: id, title: tt, cat: cat, w: w, hist: hist, cond: cond || null, text: function () { return [tx]; }, choices: choices };
  }
  function wr(s, k) { return s.world[k] || { p: 50, hostility: 30, commit: 0 }; }
  function threat(s) { return Math.max(wr(s, 'silla').hostility, wr(s, 'goguryeo').hostility, wr(s, 'tang').commit); }

  var E = [
    /* ═════ 삼국 시대의 일화 ═════ */
    EV('k_pyeonggang', ['평민 출신 무사의 발탁', 'A Commoner Warrior Is Noticed', '平民出身の武人の抜擢'], '인물', 2, '사료',
      function (s) { return s.realm.royal >= 35; },
      ['저잣거리에서 바보로 불리던 가난한 청년이 사냥 대회에서 누구보다 많은 짐승을 잡아 올렸습니다. 옛 고구려 온달은 공주의 믿음 속에 장군이 되었다고 합니다. 귀족들은 신분을 들어 그를 쓰는 것을 반대합니다.',
        'A poor young man the marketplace called a fool took more game than anyone at the hunting contest. In old Goguryeo, Ondal became a general thanks to a princess who believed in him. The nobles object, citing his low birth.',
        '市場で愚か者と呼ばれた貧しい青年が、狩猟大会で誰よりも多くの獲物を仕留めました。昔の高句麗の温達は公主の信頼のもとで将軍になったといいます。貴族たちは身分を理由に登用に反対します。'],
      [C(['신분을 따지지 않고 중용한다', 'Promote him regardless of birth', '身分を問わず重用する'],
        ['귀족 반발, 훈련·사기 +', 'Nobles resent it, training and morale up', '貴族が反発、訓練・士気上昇'],
        ['청년은 변경의 싸움에서 앞장서 병사들의 마음을 얻었습니다. 귀족들은 이를 갈았습니다.', 'The young man led from the front on the frontier and won the soldiers’ hearts. The nobles ground their teeth.', '青年は国境の戦いで先頭に立ち、兵の心を掴みました。貴族たちは歯ぎしりしました。'],
        { realm: { train: 4, royal: -2 }, fx: { morale: 4, people: 2 }, army: { baekje_bangun: 300 } }),
        C(['시험을 치러 실력이 확인되면 쓴다', 'Test him first, then use him if proven', '試験を課し、実力が確かめられれば用いる'],
          ['안전하게 인재 확보', 'A safe way to gain talent', '安全に人材を確保'],
          ['청년은 시험을 훌륭히 치렀고, 귀족들도 입을 다물었습니다.', 'He passed the test with flying colors and even the nobles fell silent.', '青年は見事に試験をこなし、貴族たちも口をつぐみました。'],
          { fx: { gold: -3 }, realm: { train: 3 }, flags: {} }),
        C(['귀족들의 뜻에 따라 쓰지 않는다', 'Bow to the nobles and pass on him', '貴族の意向に従い用いない'],
          ['왕권 +, 인재 놓침', 'Royal authority up, a talent lost', '王権上昇、人材を逃す'],
          ['청년은 조용히 떠났습니다. 훗날 이웃 나라에서 이름을 떨쳤다는 소문이 들려옵니다.', 'The young man left quietly. Word later came that he made a name in a neighboring state.', '青年は静かに去りました。のちに隣国で名を上げたという噂が聞こえてきます。'],
          { realm: { royal: 3 }, fx: { morale: -2 } })]),

    EV('k_seodong', ['아이들 노래로 퍼진 소문', 'A Rumor Spread by a Children’s Song', '童謡で広まった噂'], '정치', 1.6, '사료',
      function (s) { return s.realm.royal < 75; },
      ['저잣거리 아이들이 왕실 인물을 비방하는 노래를 부르고 다닌다는 보고입니다. 옛 백제 서동은 아이들에게 노래를 퍼뜨려 공주를 얻었다고 전해집니다. 누군가 이 노래를 이용해 조정을 흔들려는 것 같습니다.',
        'Children in the marketplace are said to be singing a song that slanders a royal. Seodong of old Baekje is said to have won a princess by spreading a song among children. Someone seems to be using this song to shake the court.',
        '市場の子どもたちが王族を中傷する歌を歌い歩いているとの報告です。昔の百済の薯童は、子どもたちに歌を広めて公主を得たと伝わります。誰かがこの歌を使って朝廷を揺さぶろうとしているようです。'],
      [C(['노래의 출처를 캐내 배후를 잡는다', 'Trace the song to its source and catch the instigator', '歌の出どころを調べ黒幕を捕らえる'],
        ['첩보 +, 왕권 +', 'Intelligence and authority up', '諜報・王権上昇'],
        ['한 귀족 가문의 하인이 노래를 퍼뜨린 사실이 밝혀졌습니다. 조정이 한결 바로잡혔습니다.', 'A servant of a noble house was found to have spread the song. The court was set right.', 'ある貴族の家の下僕が歌を広めたと判明し、朝廷は正されました。'],
        { realm: { intel: 3, royal: 3 }, fx: { gold: -3 } }),
        C(['더 좋은 노래를 지어 퍼뜨려 맞선다', 'Counter with a better song', 'より良い歌を作って広め対抗する'],
          ['금 3, 민심 +', 'Gold 3, popular mood up', '金3、民心上昇'],
          ['왕실을 기리는 새 노래가 번지자 비방의 노래는 묻혔습니다.', 'A new song praising the royal house spread and drowned out the slander.', '王室を称える新しい歌が広まり、中傷の歌は埋もれました。'],
          { fx: { gold: -3, people: 3 } }),
        C(['아이들과 부모를 엄히 단속한다', 'Crack down hard on the children and parents', '子どもと親を厳しく取り締まる'],
          ['민심 −, 소문 잠잠', 'Popular mood down, rumor quiets', '民心低下、噂は沈静'],
          ['노래는 사라졌으나 백성들 사이에 은근한 두려움이 번졌습니다.', 'The song vanished but a quiet fear spread among the people.', '歌は消えましたが、民の間に静かな恐れが広がりました。'],
          { fx: { people: -4 }, realm: { royal: 2 } })]),

    EV('k_usan', ['바다 건너 섬나라의 복속', 'Bringing the Island State to Heel', '海の向こうの島国の服属'], '군사', 1.6, '사료',
      function (s) { return s.realm.navy >= 15 && s.res.food >= 20; },
      ['동쪽 바다의 한 섬나라가 험한 지형과 파도를 믿고 조공을 바치지 않습니다. 옛 신라 이사부는 나무 사자를 배에 실어 겁을 주어 이 나라를 항복시켰다고 합니다. 군을 보내기엔 바다가 험합니다.',
        'An island state in the eastern sea trusts its rough terrain and waves and pays no tribute. Isabu of old Silla is said to have frightened such a state into surrender by loading wooden lions onto his ships. A direct assault across such seas is risky.',
        '東の海のある島国が、険しい地形と荒波を頼みに貢物を納めません。昔の新羅の異斯夫は、木で作った獅子を船に載せて脅し、この国を降伏させたといいます。軍を送るには海が険しすぎます。'],
      [C(['나무 사자를 실은 배로 위협한다', 'Frighten them with ships carrying wooden lions', '木製の獅子を載せた船で脅す'],
        ['금 4, 도박: 성공하면 무혈 복속', 'Gold 4, gamble: bloodless submission on success', '金4、賭け：成功なら無血服属'],
        null,
        { fx: { gold: -4 }, fn: R(0.55, { t: ['섬 사람들은 괴수가 실린 줄 알고 겁에 질려 항복했습니다.', 'The islanders took the wooden beasts for real and surrendered in fright.', '島の人々は怪獣が載っていると信じて怯え、降伏しました。'], fx: { gold: 8, morale: 4 }, realm: { navy: 3, royal: 2 } },
          { t: ['섬 사람들은 속임수를 눈치채고 비웃었습니다. 체면만 구겼습니다.', 'The islanders saw through the trick and laughed. Only our pride was bruised.', '島の人々は策に気づいて嘲笑しました。面目を失っただけでした。'], fx: { morale: -2 }, realm: { navy: -1 } }) }),
        C(['수군을 정식으로 보내 정벌한다', 'Send the navy for a proper conquest', '水軍を正式に送って征討する'],
          ['군량 −8, 수군력에 따라 결과', 'Food −8, result depends on naval strength', '兵糧−8、水軍力で結果が決まる'],
          null,
          { fx: { food: -8 }, fn: function (S) { return S.roll() < (S.realm.navy >= 30 ? 0.75 : 0.45) ? { realm: { navy: 3 }, fx: { gold: 8, morale: 5 }, text: USAN_OK } : { realm: { navy: -3 }, fx: { morale: -4 }, army: { baekje_navy: -200 }, text: USAN_NG }; } }),
        C(['교역으로 유도해 서서히 끌어들인다', 'Draw them in gradually through trade', '交易で誘い徐々に取り込む'],
          ['금 5, 산업 +', 'Gold 5, economy up', '金5、産業上昇'],
          ['섬의 특산물이 오가며 해마다 교류가 늘었습니다.', 'Island goods flowed in and exchange grew year by year.', '島の特産物が行き交い、年々交流が増えました。'],
          { fx: { gold: -5 }, realm: { econ: 3, navy: 1 } })]),

    EV('k_hostage', ['인질을 구하러 간 사신', 'The Envoy Sent to Rescue the Hostage', '人質を救いに行った使者'], '외교', 1.6, '사료',
      function (s) { return s.rel.goguryeo >= 20 || s.rel.silla >= 20 || s.rel.wa >= 20; },
      ['오래전 이웃 나라에 인질로 잡혀 간 왕의 아우가 아직 돌아오지 못하고 있습니다. 옛 신라 박제상은 스스로 적지에 들어가 인질을 빼돌리고 자신은 목숨을 잃었다고 합니다. 신하 하나가 그 일을 자원했습니다.',
        'The king’s younger brother, taken hostage by a neighbor long ago, still has not returned. Park Jesang of old Silla is said to have entered enemy land to smuggle out a hostage at the cost of his own life. A retainer volunteers to try the same.',
        '昔、隣国に人質として囚われた王の弟がまだ戻れずにいます。昔の新羅の朴堤上は、自ら敵地に入って人質を逃がし、自分は命を落としたといいます。一人の臣がそれを志願しました。'],
      [C(['신하를 보내 몰래 빼내 오게 한다', 'Send him to bring the hostage out in secret', '臣を送り密かに連れ出させる'],
        ['금 6, 도박: 성공하면 위신 ++', 'Gold 6, gamble: big prestige on success', '金6、賭け：成功なら威信大幅上昇'],
        null,
        { fx: { gold: -6 }, fn: R(0.5, { t: ['신하는 목숨을 걸고 왕의 아우를 빼냈습니다. 왕은 눈물로 그를 기렸습니다.', 'The retainer risked his life and brought the king’s brother home. The king honored him in tears.', '臣は命がけで王の弟を連れ出しました。王は涙ながらに彼を称えました。'], fx: { morale: 6, people: 3 }, realm: { royal: 4 } },
          { t: ['일이 들통나 신하는 붙잡혔고 이웃 나라와 사이가 크게 틀어졌습니다.', 'The plot was exposed, the retainer was seized, and relations with the neighbor soured badly.', '事が露見して臣は捕らえられ、隣国との仲が大きくこじれました。'], rel: { goguryeo: -8, silla: -8 }, fx: { morale: -3 } }) }),
        C(['사신을 보내 정식으로 몸값을 흥정한다', 'Negotiate a ransom through proper envoys', '使者を送り正式に身代金を交渉する'],
          ['금 12, 안전', 'Gold 12, safe', '金12、安全'],
          ['큰 금을 치르고 마침내 왕의 아우가 돌아왔습니다.', 'A large sum was paid and the king’s brother finally came home.', '大金を払い、ついに王の弟が帰ってきました。'],
          { fx: { gold: -12, morale: 3 }, rel: { goguryeo: 2, silla: 2 } }),
        C(['아쉽지만 때를 기다린다', 'Wait for a better time', '惜しいが時を待つ'],
          ['변화 없음', 'No change', '変化なし'],
          ['왕은 아우의 안위를 걱정하며 때를 기다리기로 했습니다.', 'The king chose to wait, worrying for his brother.', '王は弟の身を案じつつ、時を待つことにしました。'], {})]),

    EV('k_martyr', ['새 가르침을 둘러싼 싸움', 'The Fight over a New Faith', '新しい教えをめぐる争い'], '문화', 1.6, '사료',
      function (s) { return !s.flags.buddhist && s.year < 600; },
      ['바다 건너온 승려들이 퍼뜨린 새 종교가 백성 사이에서 퍼지고 있습니다. 옛 신라에서는 이차돈이 목숨을 바쳐 이 가르침을 공인받게 했다고 합니다. 귀족들은 전통 제사를 위협한다며 격렬히 반대합니다.',
        'A new religion spread by monks from overseas is catching on among the people. In old Silla, Ichadon is said to have given his life to win recognition for it. The nobles oppose it fiercely, saying it threatens the traditional rites.',
        '海を渡ってきた僧侶たちが広めた新しい宗教が、民の間に広まっています。昔の新羅では、異次頓が命を捧げてこの教えを公認させたといいます。貴族たちは伝統の祭祀を脅かすと激しく反対します。'],
      [C(['새 가르침을 공인하고 절을 세운다', 'Recognize the new faith and build temples', '新しい教えを公認し寺を建てる'],
        ['금 8, 민심 +, 귀족 반발', 'Gold 8, popular mood up, nobles angered', '金8、民心上昇、貴族が反発'],
        ['첫 절의 종소리가 울리자 백성들이 모여들었습니다. 귀족들은 불편한 기색이었습니다.', 'When the first temple bell rang the people gathered. The nobles looked uneasy.', '最初の寺の鐘が鳴ると民が集まりました。貴族たちは不機嫌な顔でした。'],
        { fx: { gold: -8, people: 5 }, realm: { royal: 2, intel: 2 }, flags: { buddhist: true } }),
        C(['전통 제사와 새 가르침을 함께 인정한다', 'Recognize both the old rites and the new faith', '伝統の祭祀と新しい教えを併せて認める'],
          ['금 4, 갈등 완화', 'Gold 4, tensions eased', '金4、対立が和らぐ'],
          ['둘을 아우르는 타협안에 대부분이 고개를 끄덕였습니다.', 'Most nodded at the compromise that embraced both.', '双方を包み込む折衷案に、大半がうなずきました。'],
          { fx: { gold: -4, people: 2 }, realm: { royal: 1 }, flags: { buddhist: true } }),
        C(['금지하고 승려를 내쫓는다', 'Ban it and expel the monks', '禁じて僧侶を追い出す'],
          ['왕권 +, 민심 −', 'Authority up, popular mood down', '王権上昇、民心低下'],
          ['귀족들은 환영했으나 새 가르침을 믿던 백성들의 눈빛이 싸늘해졌습니다.', 'The nobles were pleased, but the faces of the believers turned cold.', '貴族は歓迎しましたが、新しい教えを信じていた民の目は冷ややかになりました。'],
          { realm: { royal: 3 }, fx: { people: -4 } })]),

    EV('k_dobi', ['신하의 아내를 탐낸 왕', 'The King Who Coveted a Subject’s Wife', '臣下の妻を欲した王'], '정치', 1.2, '사료',
      function (s) { return s.realm.royal >= 55; },
      ['왕의 가까운 신하가 절개 높은 아내를 두었다는 소문이 궁에 퍼지자, 아첨하는 이들이 그 아내를 궁으로 들이라 부추깁니다. 옛 백제 도미의 이야기처럼, 권력으로 남의 가정을 짓밟는 일이 될 것입니다.',
        'Word has spread through the palace that a trusted retainer has a wife of great virtue, and flatterers urge the king to bring her to court. As in the old tale of Domi of Baekje, it would mean crushing a family with power.',
        '王の側近の臣に貞節の高い妻がいるという噂が宮中に広まり、追従する者たちは彼女を宮に迎えるよう勧めます。昔の百済の都彌の話のように、権力で他人の家庭を踏みにじることになるでしょう。'],
      [C(['단호히 거절하고 아첨꾼들을 꾸짖는다', 'Refuse firmly and rebuke the flatterers', 'きっぱり断り、追従者を叱責する'],
        ['민심·왕권 +', 'Popular mood and authority up', '民心・王権上昇'],
        ['왕의 절제가 알려지자 신하들의 믿음이 두터워졌습니다.', 'When the king’s restraint became known, his ministers’ trust deepened.', '王の自制が知れ渡ると、臣下たちの信頼は厚くなりました。'],
        { fx: { people: 3, morale: 1 }, realm: { royal: 2 } }),
        C(['그 신하를 먼 곳으로 보내 아내를 궁에 부른다', 'Send the retainer away and summon the wife', 'その臣を遠方へやり、妻を宮に呼ぶ'],
          ['도박: 불명예, 큰 반발', 'Gamble: disgrace and heavy backlash', '賭け：不名誉と大きな反発'],
          null,
          { fn: R(0.25, { t: ['아내는 순순히 응했고 소문은 가라앉았습니다. 왕은 한동안 마음이 무거웠습니다.', 'The wife complied and the rumor settled, though the king’s heart stayed heavy for a time.', '妻は素直に応じ、噂は収まりました。王はしばらく心が重いままでした。'], realm: { royal: 1 } },
            { t: ['아내는 도망치고 신하는 분노해 왕을 떠났습니다. 백성은 왕의 무도함에 혀를 찼습니다.', 'The wife fled and the retainer left the king in fury. The people clicked their tongues at his lawlessness.', '妻は逃げ、臣は怒って王のもとを去りました。民は王の無道に舌打ちしました。'], fx: { people: -7, morale: -4 }, realm: { royal: -5 } }) }),
        C(['부부를 불러 상을 내려 칭송한다', 'Summon the couple and praise them with a reward', '夫婦を呼んで賞を与え称える'],
          ['금 4, 민심 ++', 'Gold 4, popular mood sharply up', '金4、民心大幅上昇'],
          ['절개 높은 부부의 이야기가 널리 퍼졌고, 왕의 덕이 칭송되었습니다.', 'The story of the virtuous couple spread widely and the king’s virtue was praised.', '貞節な夫婦の話が広まり、王の徳が称えられました。'],
          { fx: { gold: -4, people: 5 }, realm: { royal: 2 } })]),

    EV('k_gyebaek', ['결사대를 조직하다', 'Raising a Band of Last-Stand Fighters', '決死隊を編成する'], '군사', 2.4, '사료',
      function (s) { return threat(s) >= 50 && s.realm.defense < 65; },
      ['적의 대군이 코앞인데 우리 병력은 몇 배나 적습니다. 한 장수가 가족을 스스로 베고 결사의 각오를 보이며 죽기로 싸울 군사를 모으겠다고 합니다. 옛 황산벌의 이야기가 떠오릅니다.',
        'The enemy host is at the gates and our troops are outnumbered several to one. A general proposes to rally men willing to fight to the death, showing his own resolve through a terrible sacrifice. The old tale of Hwangsanbeol comes to mind.',
        '敵の大軍が目前に迫り、味方の兵は数倍も少ない状況です。ある将軍が、決死の覚悟を示して死ぬ気で戦う兵を集めると申し出ました。昔の黄山伐の話が思い出されます。'],
      [C(['결사대를 조직해 앞세운다', 'Raise the last-stand band and put it up front', '決死隊を編成して先陣に立てる'],
        ['병력 소모, 사기 ++, 도박', 'Troops spent, morale sharply up, gamble', '兵力消耗、士気大幅上昇、賭け'],
        null,
        { fx: { gold: -5, morale: 3 }, fn: R(0.5, { t: ['결사대의 기세가 적의 선봉을 몇 번이고 물리쳤습니다. 전군이 숨을 죽이고 그 모습을 지켜봤습니다.', 'The band’s fury threw back the enemy vanguard again and again while the whole army watched in silence.', '決死隊の気迫は敵の先鋒を幾度も退け、全軍が息を呑んで見守りました。'], fx: { morale: 7 }, realm: { defense: 3, train: 2 }, world: { 'silla.p': -3 } },
          { t: ['결사대는 끝까지 싸웠으나 수가 너무 달렸습니다. 많은 용사를 잃고 말았습니다.', 'The band fought to the end but the odds were too great, and many brave men were lost.', '決死隊は最後まで戦いましたが、数の差が大きすぎました。多くの勇士を失いました。'], fx: { morale: -2 }, army: { baekje_bangun: -800 } }) }),
        C(['험한 지형을 골라 방어선을 겹겹이 세운다', 'Choose rough terrain and build layered lines', '険しい地形を選び防衛線を幾重にも築く'],
          ['금 6, 방비 ++', 'Gold 6, defense sharply up', '金6、守り大幅上昇'],
          ['세 겹의 진영이 골짜기를 막자 적의 기세가 한풀 꺾였습니다.', 'Three lines of camps blocked the valley and the enemy’s momentum slackened.', '三重の陣が谷を塞ぐと、敵の勢いは少し削がれました。'],
          { fx: { gold: -6 }, realm: { defense: 5, train: 1 } }),
        C(['사신을 보내 화친을 청한다', 'Send envoys to sue for peace', '使者を送り和睦を請う'],
          ['금 10, 위신 −', 'Gold 10, prestige down', '金10、威信低下'],
          ['큰 선물을 치르고 한숨 돌릴 시간을 얻었습니다. 그러나 체면은 크게 상했습니다.', 'A big gift bought breathing room but our pride was badly damaged.', '大きな贈り物で一息つく時間を得ましたが、面目は大きく傷つきました。'],
          { fx: { gold: -10, morale: -3 }, rel: { silla: 4, goguryeo: 4, tang: 4 }, world: { 'tang.commit': -3, 'silla.hostility': -4 } })]),

    EV('k_ansi', ['고립된 성의 항전', 'The Besieged Fort Holds Out', '孤立した城の抗戦'], '군사', 1.8, '사료',
      function (s) { return threat(s) >= 40 && s.realm.defense >= 25; },
      ['대군에 에워싸인 변경의 성이 석 달째 버티고 있습니다. 성주가 식량이 바닥나고 있다며 증원을 간청합니다. 옛 안시성은 대군 앞에서 토산을 쌓는 적에 맞서 끝내 이겨 냈다고 합니다.',
        'A border fort ringed by a great host has held out for three months. The commander begs for reinforcements as supplies run out. The old fort of Ansi is said to have beaten an enemy that piled up an earthen ramp before it.',
        '大軍に囲まれた国境の城が三か月持ちこたえています。城主は食糧が尽きかけているとして増援を懇願します。昔の安市城は、土山を築く敵に屈せずついに勝ち抜いたといいます。'],
      [C(['곡식과 병력을 몰래 들여보낸다', 'Slip grain and men into the fort', '穀物と兵を密かに送り込む'],
        ['군량 −8, 병력 −, 성 사기 +', 'Food −8, troops −, fort morale up', '兵糧−8、兵力−、城の士気上昇'],
        ['밤길을 달린 수송대가 성에 닿자 성안에서 함성이 터졌습니다.', 'When the night convoy reached the fort, a roar went up from within.', '夜道を駆けた輸送隊が城に着くと、城内で歓声が上がりました。'],
        { fx: { food: -8, morale: 4 }, army: { baekje_levy: -300 }, realm: { defense: 3 } }),
        C(['적의 후방을 쳐 포위를 풀게 한다', 'Strike the enemy rear to break the siege', '敵の後方を突き包囲を解かせる'],
          ['도박: 성공하면 큰 승리', 'Gamble: a great victory on success', '賭け：成功なら大勝'],
          null,
          { fn: R(0.45, { t: ['후방이 흔들린 적이 포위를 풀고 물러났습니다. 성은 지켜졌습니다.', 'With its rear shaken the enemy lifted the siege and withdrew. The fort was saved.', '後方を揺さぶられた敵は包囲を解き、退きました。城は守られました。'], fx: { morale: 7, gold: 5 }, world: { 'silla.p': -4, 'tang.commit': -3 } },
            { t: ['후방 부대가 오히려 적의 역습에 걸렸습니다. 성도 끝내 함락되었습니다.', 'Our rear force was caught by an enemy counterstrike and the fort fell in the end.', '後方部隊はかえって敵の逆襲に遭い、城もついに陥落しました。'], fx: { morale: -6, people: -3 }, army: { baekje_bangun: -500 }, realm: { defense: -4 } }) }),
        C(['성주에게 항복을 허락한다', 'Allow the commander to surrender', '城主に降伏を許す'],
          ['방비 −, 병사 구함', 'Defense down, soldiers spared', '守り低下、兵を救う'],
          ['성은 내주었으나 병사와 백성은 목숨을 건졌습니다.', 'The fort was given up but its soldiers and people were saved.', '城は明け渡しましたが、兵と民は命を救われました。'],
          { realm: { defense: -4 }, fx: { morale: -3, people: 1 } })]),

    EV('k_salsu', ['지친 적을 깊이 끌어들이다', 'Drawing the Weary Enemy Deep', '疲れた敵を深く誘い込む'], '군사', 2, '사료',
      function (s) { return s.realm.intel >= 25 && threat(s) >= 40; },
      ['대군이 국경을 넘어 깊이 들어오고 있습니다. 한 장수가 짐짓 싸우다 달아나기를 되풀이해 적을 지치게 하고, 강을 건너는 순간 치자는 계책을 올렸습니다. 옛 살수에서 을지문덕이 쓴 방법입니다.',
        'A great army is pushing deep across the border. A general proposes to feign fighting and flee again and again to wear the enemy down, then strike as it crosses a river. It is the method Eulji Mundeok used at the old Salsu.',
        '大軍が国境を越えて深く入り込んできます。ある将軍が、戦うふりをして逃げることを繰り返して敵を疲れさせ、川を渡る瞬間に討つ策を進言しました。昔、薩水で乙支文徳が用いた方法です。'],
      [C(['유인책을 쓰고 강가에 병력을 숨긴다', 'Use the lure and hide troops by the river', '誘い込みの策を使い、川辺に兵を伏せる'],
        ['도박: 성공하면 대승', 'Gamble: a great victory on success', '賭け：成功なら大勝'],
        null,
        { fx: { gold: -5 }, fn: function (S) { return S.roll() < (S.realm.intel >= 40 ? 0.7 : 0.45) ? { fx: { morale: 9, gold: 8 }, world: { 'silla.p': -6, 'tang.commit': -6 }, realm: { train: 3, intel: 2 }, text: SALSU_OK } : { fx: { morale: -5 }, army: { baekje_bangun: -600 }, text: SALSU_NG }; } }),
        C(['성에서 버티며 적의 보급이 끊기길 기다린다', 'Hold the forts and wait for the enemy supply to fail', '城で粘り、敵の補給が切れるのを待つ'],
          ['금 5, 방비 +', 'Gold 5, defense up', '金5、守り上昇'],
          ['적의 보급이 늘어나 약해질 때까지 버텼고 큰 피해 없이 물러가게 했습니다.', 'We held until the stretched enemy supply thinned, and drove them off with little damage.', '伸びきった敵の補給が細るまで持ちこたえ、大きな被害なく退かせました。'],
          { fx: { gold: -5 }, realm: { defense: 3 }, world: { 'silla.p': -1 } }),
        C(['정면으로 맞서 결전한다', 'Face them in a decisive battle', '正面から迎え撃ち決戦する'],
          ['병력 소모, 승패는 훈련에 달림', 'Troops spent, outcome depends on training', '兵力消耗、勝敗は訓練次第'],
          null,
          { fn: function (S) { return S.roll() < (S.realm.train >= 60 ? 0.55 : 0.3) ? { fx: { morale: 6 }, army: { baekje_bangun: -400 }, world: { 'silla.p': -3 }, text: SALSU_FRONT_OK } : { fx: { morale: -6, people: -2 }, army: { baekje_bangun: -900 }, realm: { defense: -3 }, text: SALSU_FRONT_NG }; } })]),

    EV('k_coup', ['권신의 정변 조짐', 'A Powerful Minister Eyes a Coup', '権臣の政変の兆し'], '정치', 2.2, '사료',
      function (s) { return s.realm.royal < 45; },
      ['조정에서 가장 힘센 권신이 병권을 쥐고 왕의 명을 가려 듣기 시작했습니다. 그가 은밀히 군을 불러 모은다는 소문까지 돕니다. 옛 고구려에서는 권신이 정변을 일으켜 왕을 몰아내고 실권을 장악한 일이 있었습니다.',
        'The most powerful minister at court holds the military and has begun choosing which royal orders to hear. Rumor even says he is secretly gathering troops. In old Goguryeo a powerful minister once seized power in a coup and cast out the king.',
        '朝廷で最も力のある権臣が兵権を握り、王の命令を選り好みして聞くようになりました。ひそかに兵を集めているという噂まで流れています。昔の高句麗では、権臣が政変を起こし王を追って実権を握ったことがありました。'],
      [C(['선수를 쳐 그를 제거한다', 'Strike first and remove him', '先手を打って排除する'],
        ['도박: 성공하면 왕권 ++, 실패하면 위기', 'Gamble: big authority on success, crisis on failure', '賭け：成功なら王権大幅上昇、失敗なら危機'],
        null,
        { fn: R(0.45, { t: ['왕의 계획이 맞아떨어져 권신은 쓰러지고 조정이 다시 왕의 손에 들어왔습니다.', 'The king’s plan worked: the minister fell and the court returned to the king’s hands.', '王の計画が当たり、権臣は倒れ、朝廷は再び王の手に戻りました。'], realm: { royal: 8 }, fx: { morale: 3 } },
          { t: ['계획이 새어 나가 권신이 먼저 군을 움직였습니다. 궁이 크게 흔들렸습니다.', 'The plan leaked and the minister moved his troops first. The palace was badly shaken.', '計画が漏れ、権臣が先に軍を動かしました。宮中は大きく揺れました。'], realm: { royal: -9 }, fx: { people: -4, morale: -5 }, army: { baekje_guard: -200 } }) }),
        C(['관직과 땅을 주어 달래며 힘을 키운다', 'Appease him with posts and land while gaining strength', '官職と土地を与えて宥め、力を蓄える'],
          ['금 8, 시간을 번다', 'Gold 8, buys time', '金8、時間を稼ぐ'],
          ['권신은 만족해 한동안 잠잠해졌습니다. 그 사이 왕은 친위 세력을 다졌습니다.', 'The minister was satisfied and quiet for a while, during which the king built up his loyal forces.', '権臣は満足してしばらく静かになりました。その間に王は親衛勢力を固めました。'],
          { fx: { gold: -8 }, realm: { royal: 2, train: 1 } }),
        C(['대신들을 모아 공개적으로 권력 남용을 따진다', 'Gather the ministers and openly confront the abuse', '大臣を集め、権力の乱用を公然と問い質す'],
          ['왕권 ±, 대신들의 태도에 달림', 'Authority up or down, depends on the ministers', '王権±、大臣たちの出方次第'],
          null,
          { fn: R(0.5, { t: ['대신들이 왕의 편에 서자 권신은 자리에서 물러났습니다.', 'The ministers sided with the king and the minister stepped down.', '大臣たちが王の側に立つと、権臣は退きました。'], realm: { royal: 5 } },
            { t: ['대신들이 눈치만 보자 권신은 오히려 더 기세등등해졌습니다.', 'The ministers only watched which way the wind blew and the minister grew even bolder.', '大臣たちが様子見に徹すると、権臣はかえって勢いづきました。'], realm: { royal: -4 } }) })]),

    EV('k_omen', ['별이 떨어졌다는 소문', 'The Rumor of a Falling Star', '星が落ちたという噂'], '전조', 1.8, '사료',
      function (s) { return s.realm.royal < 60 || s.res.morale < 55; },
      ['밤하늘에 큰 별이 떨어졌고, 별이 떨어지면 지도자가 패한다는 오래된 믿음에 병사들이 동요합니다. 불만을 품은 이들은 이를 핑계로 반란을 부추깁니다. 옛 신라에서는 이런 불길한 징조를 다른 징조로 덮어 사기를 되살린 일이 있었습니다.',
        'A great star has fallen in the night sky, and soldiers are shaken by the old belief that a falling star means the leader will fall. Malcontents use it as a pretext to stir revolt. In old Silla, such an ill omen was once covered by another sign to restore morale.',
        '夜空に大きな星が落ち、星が落ちれば指導者が敗れるという古い言い伝えに兵が動揺しています。不満を抱く者はそれを口実に反乱をあおります。昔の新羅では、こうした不吉な兆しを別の兆しで覆って士気を取り戻したことがありました。'],
      [C(['불덩이를 하늘로 띄워 별이 돌아갔다고 선포한다', 'Launch a fire lantern and declare the star has returned', '火の玉を空に上げ、星が帰ったと宣言する'],
        ['금 3, 도박: 성공하면 사기 ++', 'Gold 3, gamble: morale sharply up on success', '金3、賭け：成功なら士気大幅上昇'],
        null,
        { fx: { gold: -3 }, fn: R(0.6, { t: ['불덩이가 하늘로 오르자 병사들은 별이 돌아갔다며 환호했습니다.', 'When the fireball rose the soldiers cheered that the star had returned.', '火の玉が空へ昇ると、兵たちは星が帰ったと歓声を上げました。'], fx: { morale: 7 }, realm: { royal: 3 } },
          { t: ['속임수가 알려져 병사들은 더 불안해했고 반란의 핑계만 늘었습니다.', 'The trick was exposed and the soldiers grew more uneasy, giving the rebels more pretext.', '仕掛けが知れ渡り、兵はいっそう不安になり、反乱の口実が増えました。'], fx: { morale: -4 }, realm: { royal: -3 } }) }),
        C(['천문관의 해석을 구하고 제사를 올린다', 'Consult the astronomers and hold rites', '天文官の解釈を求め祭祀を行う'],
          ['금 5, 민심 +', 'Gold 5, popular mood up', '金5、民心上昇'],
          ['천문관이 길한 해석을 내놓자 동요가 가라앉았습니다.', 'The astronomer gave an auspicious reading and the unrest subsided.', '天文官が吉の解釈を示すと、動揺は収まりました。'],
          { fx: { gold: -5, people: 2, morale: 2 } }),
        C(['미신이라며 무시하고 선동자를 벌한다', 'Dismiss it as superstition and punish agitators', '迷信として無視し、扇動者を罰する'],
          ['왕권 +, 사기 −', 'Authority up, morale down', '王権上昇、士気低下'],
          ['선동자는 조용해졌으나 병사들의 불안은 가시지 않았습니다.', 'The agitators went quiet but the soldiers’ unease did not fade.', '扇動者は静かになりましたが、兵の不安は消えませんでした。'],
          { realm: { royal: 3 }, fx: { morale: -3 } })]),

    EV('k_exile', ['망명 악사의 후원', 'Patronage for an Exiled Musician', '亡命楽人の後援'], '문화', 1.4, '사료', null,
      ['멸망한 작은 나라에서 열두 줄 현악기를 다루는 악사가 제자들과 함께 피난해 왔습니다. 그의 음악은 구슬프면서도 아름다워 궁중에서도 소문이 자자합니다. 그를 후원하면 문화가 꽃피지만, 이웃 나라의 눈치를 봐야 합니다.',
        'A musician who plays a twelve-stringed zither has fled with his pupils from a fallen small state. His music is plaintive and beautiful and the court speaks of little else. Patronage would let culture bloom, but we must mind the neighbors.',
        '滅びた小国から、十二弦の琴を奏でる楽人が弟子とともに逃れてきました。その音楽は物悲しくも美しく、宮中でも評判です。後援すれば文化は花開きますが、隣国の目を気にしなければなりません。'],
      [C(['궁에서 후원하고 제자를 기른다', 'Patronize him at court and raise pupils', '宮廷で後援し、弟子を育てる'],
        ['금 6, 민심·왕권 +', 'Gold 6, popular mood and authority up', '金6、民心・王権上昇'],
        ['새 악기와 곡이 도성에 퍼지자 문화가 새로워졌습니다.', 'New instruments and tunes spread through the capital and renewed its culture.', '新しい楽器と曲が都に広まり、文化が一新されました。'],
        { fx: { gold: -6, people: 3 }, realm: { royal: 2, intel: 1 } }),
        C(['조용히 지방에서 지내게 한다', 'Let him live quietly in the provinces', '静かに地方で暮らさせる'],
          ['금 2', 'Gold 2', '金2'],
          ['악사는 시골 마을에서 제자를 가르치며 조용히 지냈습니다.', 'The musician taught pupils in a country village and lived quietly.', '楽人は田舎の村で弟子を教え、静かに暮らしました。'],
          { fx: { gold: -2, people: 1 } }),
        C(['이웃의 요구대로 돌려보낸다', 'Return him as the neighbor demands', '隣国の要求どおり送り返す'],
          ['관계 +, 평판 −', 'Relations up, reputation down', '関係上昇、評判低下'],
          ['이웃은 만족했으나 악사의 운명을 아는 이들은 왕을 비난했습니다.', 'The neighbor was satisfied, but those who knew the musician’s fate blamed the king.', '隣国は満足しましたが、楽人の運命を知る者は王を非難しました。'],
          { rel: { silla: 4, goguryeo: 4 }, fx: { people: -2 } })]),

    EV('k_capital', ['도읍을 옮기자는 건의', 'A Proposal to Move the Capital', '遷都の建議'], '정치', 1.2, '사료',
      function (s) { return s.res.gold >= 25 && s.realm.royal >= 40; },
      ['도성이 적의 대군과 너무 가까워 위태롭다는 의견과, 넓은 평야와 강이 있는 새 땅으로 옮기면 나라가 번성하리라는 의견이 맞섭니다. 옛 고구려는 평양으로, 백제는 사비로 도읍을 옮긴 일이 있습니다.',
        'Some say the capital is too close to the enemy host to be safe, while others say a move to broad plains and rivers would let the realm flourish. Old Goguryeo moved its capital to Pyongyang and Baekje moved to Sabi.',
        '都が敵の大軍に近すぎて危ういという意見と、広い平野と川のある新天地に移れば国が栄えるという意見が対立します。昔、高句麗は平壌に、百済は泗沘に都を移しました。'],
      [C(['새 땅에 도읍을 옮긴다', 'Move the capital to the new site', '新しい地に都を移す'],
        ['금 20, 민심 −, 산업·방비 ++', 'Gold 20, popular mood down, economy and defense sharply up', '金20、民心低下、産業・守り大幅上昇'],
        ['대공사 끝에 새 도성이 올랐습니다. 이사하는 이들의 불만도 컸으나 나라의 기운이 새로워졌습니다.', 'After great works a new capital rose. Those who had to move complained loudly but the realm felt renewed.', '大工事の末に新しい都ができました。移る人々の不満は大きかったものの、国の気運は新たになりました。'],
        { fx: { gold: -20, people: -4 }, realm: { econ: 5, defense: 5, royal: 3 } }),
        C(['현 도성의 성곽을 늘리고 강화한다', 'Expand and strengthen the current walls', '現在の都の城郭を広げて強化する'],
          ['금 12, 방비 +', 'Gold 12, defense up', '金12、守り上昇'],
          ['성벽이 높아지고 해자가 깊어졌습니다.', 'The walls rose higher and the moat grew deeper.', '城壁は高くなり、堀は深くなりました。'],
          { fx: { gold: -12 }, realm: { defense: 5 } }),
        C(['논의를 접고 현상을 유지한다', 'Drop the debate and keep the status quo', '議論を打ち切り現状を維持する'],
          ['변화 없음', 'No change', '変化なし'],
          ['도읍은 그대로이고 논의는 흐지부지되었습니다.', 'The capital stayed where it was and the debate faded away.', '都はそのままで、議論はうやむやになりました。'], {})]),

    EV('k_pagoda', ['하늘에 닿는 탑을 세우자', 'A Tower Reaching the Sky', '天に届く塔を建てよう'], '문화', 1.4, '사료',
      function (s) { return s.res.gold >= 28 && s.res.people >= 45; },
      ['나라의 위엄을 널리 알리고 이웃 나라의 침입을 막아 줄 신비한 힘을 얻기 위해, 도성에 여러 층의 거대한 탑을 세우자는 건의가 올라왔습니다. 옛 신라는 구층 목탑으로 아홉 이웃 나라를 누른다는 뜻을 세웠습니다.',
        'A proposal comes to raise a huge multi-storied tower in the capital to proclaim the realm’s dignity and gain a mystic power against invaders. Old Silla built a nine-storied wooden pagoda with the meaning of subduing nine neighboring peoples.',
        '国の威厳を広く示し、外敵の侵入を防ぐ神秘の力を得るため、都に何層もの巨大な塔を建てようという建言が上がりました。昔の新羅は九層の木塔で九つの隣国を抑える意を込めました。'],
      [C(['웅장한 탑을 짓는다', 'Build the grand tower', '壮大な塔を建てる'],
        ['금 25, 왕권·민심·사기 +', 'Gold 25, authority, popular mood and morale up', '金25、王権・民心・士気上昇'],
        ['탑이 하늘을 찌르자 도성 사람들은 눈물을 글썽였습니다. 이웃 나라 사절들도 놀랐습니다.', 'As the tower pierced the sky, the capital’s people teared up and even foreign envoys were awed.', '塔が天を突くと、都の人々は目を潤ませ、隣国の使節も驚きました。'],
        { fx: { gold: -25, people: 5, morale: 4 }, realm: { royal: 5 } }),
        C(['규모를 줄여 소박한 탑을 짓는다', 'Build a smaller, modest tower', '規模を縮小して質素な塔を建てる'],
          ['금 10, 소폭 상승', 'Gold 10, modest gains', '金10、小幅上昇'],
          ['소박한 탑이 섰으나 도성 사람들은 만족했습니다.', 'A modest tower rose and the capital’s people were content.', '質素な塔が建ち、都の人々は満足しました。'],
          { fx: { gold: -10, people: 2, morale: 1 }, realm: { royal: 2 } }),
        C(['돈은 군비에 쓰겠다며 거절한다', 'Refuse and put the money into arms', '金は軍備に使うと断る'],
          ['금 +, 방비 +', 'Gold saved, defense up', '金を節約、守り上昇'],
          ['탑 대신 병기와 성벽에 돈이 쓰였습니다.', 'Instead of a tower, funds went to weapons and walls.', '塔の代わりに武器と城壁に金が使われました。'],
          { fx: { gold: -4 }, realm: { defense: 3, train: 1 } })]),

    EV('k_tour', ['국경을 순행하고 비석을 세우다', 'A Royal Tour and a Boundary Stele', '国境を巡行し碑を建てる'], '정치', 1.6, '사료',
      function (s) { return s.realm.royal >= 45 && s.res.morale >= 45; },
      ['왕이 새로 넓힌 땅과 국경 지대를 직접 순행하며 백성을 위로하고 경계에 비석을 세우자는 건의가 올라왔습니다. 옛 신라 진흥왕은 순수비를 세워 새 영토에 왕의 위엄을 새겼습니다.',
        'A proposal asks the king to tour the newly widened land and the border in person, comfort the people and raise boundary steles. King Jinheung of old Silla set up tour steles to carve royal authority into new territory.',
        '王が新たに広げた土地と国境地帯を自ら巡行して民を慰め、境に碑を建てようという建言が上がりました。昔の新羅の真興王は巡狩碑を建て、新領土に王の威厳を刻みました。'],
      [C(['성대한 순행을 하고 비석을 세운다', 'Make a grand tour and raise the steles', '盛大に巡行し碑を建てる'],
        ['금 9, 왕권·민심 ++', 'Gold 9, authority and popular mood sharply up', '金9、王権・民心大幅上昇'],
        ['왕의 행렬이 지나자 고을마다 환호가 일었습니다. 비석은 국경의 이정표가 되었습니다.', 'As the king’s procession passed, each district cheered. The steles became frontier landmarks.', '王の行列が通ると、郡ごとに歓声が上がりました。碑は国境の道標となりました。'],
        { fx: { gold: -9, people: 5, morale: 3 }, realm: { royal: 5 } }),
        C(['간소한 순행으로 민정만 살핀다', 'A plain tour to see conditions only', '簡素な巡行で民情だけを見る'],
          ['금 3, 민심 +', 'Gold 3, popular mood up', '金3、民心上昇'],
          ['왕이 직접 백성의 사정을 듣자 몇몇 억울한 일이 풀렸습니다.', 'Hearing the people directly, the king settled several grievances.', '王が民の事情を直接聞くと、いくつかの不満が解決しました。'],
          { fx: { gold: -3, people: 3 }, realm: { intel: 1 } }),
        C(['수도를 비울 수 없다며 사양한다', 'Decline, as the capital cannot be left', '都を空けられないと辞退する'],
          ['변화 없음', 'No change', '変化なし'],
          ['순행은 취소되었습니다.', 'The tour was canceled.', '巡行は取りやめになりました。'], {})]),

    EV('k_wa_request', ['바다 건너 구원을 청하다', 'A Plea for Help from Across the Sea', '海の向こうから救援を求める'], '외교', 1.4, '사료',
      function (s) { return s.rel.wa >= 20 && s.res.food >= 25; },
      ['바다 건너 동맹이 우리에게 원군과 식량을 청해 왔습니다. 위기에 빠진 그들을 도우면 오랜 우호가 굳어지겠지만, 먼 바다를 건너는 원정에는 큰 위험이 따릅니다. 옛 백제는 왜와 손잡고 먼 길을 갔다가 낭패를 본 일이 있습니다.',
        'An ally across the sea asks us for troops and food. Helping them in their crisis would cement an old friendship, but an expedition across the open sea carries great risk. Old Baekje once teamed with its overseas ally and suffered a disaster on a distant campaign.',
        '海の向こうの同盟国が援軍と食糧を求めてきました。危機に陥った彼らを助ければ古い友好は固まりますが、遠い海を渡る遠征には大きな危険が伴います。昔の百済は倭と手を結び、遠征で痛い目を見たことがあります。'],
      [C(['곡식과 병기만 배로 보낸다', 'Send grain and arms by ship only', '穀物と武器だけを船で送る'],
        ['군량 −8, 관계 +', 'Food −8, relations up', '兵糧−8、関係上昇'],
        ['배가 무사히 닿아 동맹은 크게 감사했습니다.', 'The ships arrived safely and the ally was deeply grateful.', '船は無事に着き、同盟国は深く感謝しました。'],
        { fx: { food: -8 }, rel: { wa: 8 } }),
        C(['원군을 직접 보낸다', 'Send an expeditionary army in person', '援軍を直接送る'],
          ['병력 소모, 도박', 'Troops spent, gamble', '兵力消耗、賭け'],
          null,
          { army: { baekje_levy: -400 }, fn: R(0.4, { t: ['원군이 큰 공을 세우자 동맹은 우리의 의리를 높이 샀습니다.', 'Our expedition won great success and the ally praised our loyalty.', '援軍が大きな功を立て、同盟国はこちらの義理を高く評価しました。'], rel: { wa: 12 }, fx: { morale: 4, gold: 6 } },
            { t: ['먼 바다에서 큰 손실을 입었고 원정은 실패로 끝났습니다.', 'We suffered heavy losses at sea and the expedition ended in failure.', '遠い海で大損害を受け、遠征は失敗に終わりました。'], rel: { wa: 4 }, fx: { morale: -5 }, army: { baekje_navy: -300 } }) }),
        C(['정중히 사양하고 사정을 설명한다', 'Politely decline and explain', '丁重に辞退し事情を説明する'],
          ['관계 −', 'Relations down', '関係低下'],
          ['동맹은 서운해했으나 사정은 이해했습니다.', 'The ally was disappointed but understood.', '同盟国は残念がりましたが、事情は理解しました。'],
          { rel: { wa: -5 } })]),

    EV('k_small_state', ['작은 나라가 귀부를 청하다', 'A Small State Asks to Join Us', '小国が帰属を願い出る'], '외교', 1.8, '사료',
      function (s) { return s.realm.royal >= 40; },
      ['강한 이웃에 시달리던 작은 나라가 우리에게 나라를 들어 귀부하겠다고 청합니다. 땅과 사람이 늘지만 그들의 적과 마주해야 합니다. 옛 가야의 소국들이 이웃 강국에 흡수되던 것과 같은 일입니다.',
        'A small state hounded by a strong neighbor asks to join us with its whole land. We would gain land and people but would face their enemy. It is like the small Gaya states being absorbed by powerful neighbors.',
        '強い隣国に悩まされていた小国が、国を挙げて帰属したいと申し出ます。土地と人は増えますが、その敵と向き合わねばなりません。昔の伽耶の小国が隣の強国に吸収されたのと同じことです。'],
      [C(['받아들여 영토와 군을 흡수한다', 'Accept and absorb their land and troops', '受け入れて領土と軍を吸収する'],
        ['병력 +, 이웃 적의 +', 'Troops up, neighbor hostility up', '兵力上昇、隣国の敵意上昇'],
        ['성문이 열리고 소국의 왕이 무릎을 꿇었습니다. 그러나 이웃의 눈초리가 날카로워졌습니다.', 'The gates opened and the small king knelt. But our strong neighbor’s gaze sharpened.', '城門が開き、小国の王がひざまずきました。しかし隣国の視線は鋭くなりました。'],
        { army: { baekje_levy: 700 }, fx: { gold: 6, people: 2 }, world: { 'silla.hostility': 6 }, realm: { royal: 2 } }),
        C(['보호국으로 삼고 공물만 받는다', 'Make them a protectorate and take tribute only', '保護国として貢物だけ受け取る'],
          ['금 +8, 의무 약함', 'Gold +8, light obligation', '金+8、義務は軽い'],
          ['보호국이 된 소국은 해마다 공물을 바쳤습니다.', 'The protectorate sent tribute year after year.', '保護国となった小国は毎年貢物を納めました。'],
          { fx: { gold: 8 }, world: { 'silla.hostility': 2 } }),
        C(['이웃과의 마찰을 피해 거절한다', 'Refuse to avoid friction with the neighbor', '隣国との摩擦を避けて断る'],
          ['관계 +', 'Relations up', '関係上昇'],
          ['소국의 사절은 풀이 죽어 돌아갔습니다. 이웃은 우리의 신중함을 높이 샀습니다.', 'The small state’s envoys left dejected, while the neighbor valued our prudence.', '小国の使節は肩を落として帰りました。隣国はこちらの慎重さを評価しました。'],
          { rel: { silla: 4, goguryeo: 3 } })]),

    /* ═════ 고전 사례 ═════ */
    EV('c_baeksu', ['등 뒤에 강을 두고 싸우다', 'Fighting with a River at Our Backs', '背水の陣'], '군사', 1.8, '일반',
      function (s) { return threat(s) >= 40 && s.res.morale >= 40; },
      ['적은 우리보다 훨씬 많고, 병사들의 마음은 흔들립니다. 한 장수가 강을 등지고 진을 쳐 도망갈 길을 없애 죽기로 싸우게 하자고 합니다. 옛 한신이 쓴 배수진입니다.',
        'The enemy far outnumbers us and the soldiers waver. A general proposes camping with the river at our backs so there is no way to flee and the men must fight to the death. It is the old Han Xin river-at-the-back formation.',
        '敵は味方よりはるかに多く、兵の心は揺らいでいます。ある将軍が川を背に陣を敷き、逃げ道をなくして死ぬ気で戦わせようと言います。昔、韓信が用いた背水の陣です。'],
      [C(['강을 등지고 진을 친다', 'Camp with the river at our backs', '川を背に陣を敷く'],
        ['도박: 성공하면 사기 ++', 'Gamble: morale sharply up on success', '賭け：成功なら士気大幅上昇'],
        null,
        { fn: function (S) { return S.roll() < (S.realm.train >= 50 ? 0.6 : 0.4) ? { fx: { morale: 8 }, realm: { train: 3 }, world: { 'silla.p': -3 }, text: BAESU_OK } : { fx: { morale: -6 }, army: { baekje_bangun: -700 }, text: BAESU_NG }; } }),
        C(['험한 산성에 의지해 지킨다', 'Rely on a rugged mountain fort', '険しい山城に頼って守る'],
          ['금 4, 방비 +', 'Gold 4, defense up', '金4、守り上昇'],
          ['산성에 의지해 싸우니 병사들은 마음을 놓았습니다.', 'Fighting from a mountain fort put the soldiers at ease.', '山城を頼りに戦うと、兵たちは安心しました。'],
          { fx: { gold: -4 }, realm: { defense: 3 } }),
        C(['병사들을 위로하고 구원군을 기다린다', 'Comfort the troops and wait for relief', '兵を慰め、救援軍を待つ'],
          ['금 5, 사기 +', 'Gold 5, morale up', '金5、士気上昇'],
          ['술과 고기가 내려지자 병사들의 얼굴이 풀렸습니다.', 'With wine and meat handed out the soldiers’ faces relaxed.', '酒と肉が振る舞われると、兵の表情が和らぎました。'],
          { fx: { gold: -5, morale: 4 } })]),

    EV('c_wuqi', ['병사의 종기를 빨아 준 장수', 'The General Who Tended His Soldier’s Wound', '兵の腫れ物を吸った将軍'], '인물', 1.6, '일반',
      function (s) { return s.res.morale < 70; },
      ['한 장수가 병든 병사의 상처를 직접 입으로 빨아 낫게 해 주었다는 이야기가 군영에 퍼졌습니다. 병사들이 감동했으나, 옛 오기는 그렇게 병사의 마음을 얻어 천하의 명장이 되었다고 합니다. 이 장수를 더 중용할지 정해야 합니다.',
        'The story has spread through the camps that a general tended a sick soldier’s festering wound by hand. The men were moved. Wu Qi of old won his soldiers’ hearts this way and became a famed general. We must decide how far to promote this officer.',
        'ある将軍が病んだ兵の傷を自ら口で吸って癒したという話が軍営に広まりました。兵たちは感動しました。昔の呉起はそうして兵の心を掴み名将となったといいます。この将軍をさらに重用するか決めなければなりません。'],
      [C(['장수를 중용하고 병사 돌보는 법을 퍼뜨린다', 'Promote him and spread his way of caring for troops', '将軍を重用し、兵を気遣う作法を広める'],
        ['금 5, 사기·훈련 +', 'Gold 5, morale and training up', '金5、士気・訓練上昇'],
        ['장수들이 병사를 돌보는 풍토가 퍼지며 군의 결속이 높아졌습니다.', 'A culture of caring for the troops spread among the officers and unit cohesion rose.', '将官が兵を気遣う風土が広がり、軍の結束が高まりました。'],
        { fx: { gold: -5, morale: 5 }, realm: { train: 3 } }),
        C(['상만 내리고 평상대로 둔다', 'Reward him and leave things as they are', '賞を与えるだけで従来どおりにする'],
          ['금 2, 사기 +', 'Gold 2, morale up', '金2、士気上昇'],
          ['상을 받은 장수는 더 열심히 병사를 돌보았습니다.', 'Rewarded, the general cared for his men all the more.', '賞を受けた将軍は、いっそう熱心に兵の面倒を見ました。'],
          { fx: { gold: -2, morale: 2 } }),
        C(['사람의 마음을 사려는 계산이라며 의심한다', 'Suspect it as a bid to buy hearts', '人心を買う計算だと疑う'],
          ['왕권 +, 사기 −', 'Authority up, morale down', '王権上昇、士気低下'],
          ['왕이 의심하자 장수는 병사를 돌보는 일을 그만두었습니다. 병사들의 사기가 조금 꺾였습니다.', 'When the king grew suspicious, the general stopped tending his men and morale dipped slightly.', '王が疑うと、将軍は兵の世話をやめました。兵の士気が少し落ちました。'],
          { realm: { royal: 2 }, fx: { morale: -3 } })]),

    EV('c_xiaohe', ['후방을 맡길 재상', 'Who Will Keep the Rear?', '後方を任せる宰相'], '인물', 1.6, '일반',
      function (s) { return s.res.food < 60; },
      ['전쟁이 길어지자 곡식과 장정을 끊임없이 대 줄 후방 책임자가 절실합니다. 옛 한나라의 소하는 전장에 나가지 않고도 군량과 병력을 끊임없이 대어 승리를 이끌었다고 합니다. 후보는 행정에 밝은 노신과 야심 찬 젊은 장수입니다.',
        'With the war dragging on, we badly need a rear chief to supply grain and men without end. Xiao He of old Han never took the field yet fed the army and filled its ranks to win the war. The candidates are an administration-savvy old minister and an ambitious young general.',
        '戦が長引き、穀物と壮丁を絶えず送る後方の責任者が切実に必要です。昔の漢の蕭何は戦場に出ずに兵糧と兵力を送り続け、勝利を導いたといいます。候補は行政に明るい老臣と、野心ある若い将軍です。'],
      [C(['행정에 밝은 노신에게 맡긴다', 'Entrust it to the old administrator', '行政に明るい老臣に任せる'],
        ['금 3, 군량·산업 +', 'Gold 3, food and economy up', '金3、兵糧・産業上昇'],
        ['노신은 장부를 정리하고 곳간을 바로잡아 군량이 안정되었습니다.', 'The old minister straightened the books and granaries, and food supply steadied.', '老臣は帳簿を整理し蔵を正して、兵糧が安定しました。'],
        { fx: { gold: -3, food: 8 }, realm: { econ: 3 } }),
        C(['젊은 장수에게 맡겨 군과 후방을 합친다', 'Give it to the young general to unite army and rear', '若い将軍に任せ軍と後方を一つにする'],
          ['도박: 성공하면 군 효율 +', 'Gamble: army efficiency up on success', '賭け：成功なら軍の効率上昇'],
          null,
          { fn: R(0.5, { t: ['젊은 장수의 추진력으로 보급과 훈련이 척척 맞물렸습니다.', 'The young general’s drive meshed supply and training smoothly.', '若い将軍の推進力で補給と訓練がうまく噛み合いました。'], fx: { food: 8, morale: 3 }, realm: { train: 3 } },
            { t: ['장부 일에 서툰 장수는 곳간을 바닥내 군량이 어지러워졌습니다.', 'Unskilled with ledgers, the general emptied the granaries and threw supply into disarray.', '帳簿仕事に不慣れな将軍は蔵を空にし、兵糧が混乱しました。'], fx: { food: -8, morale: -3 } }) }),
        C(['두 사람이 서로 견제하게 나눠 맡긴다', 'Split it so the two check each other', '二人に分担させて互いに牽制させる'],
          ['금 4, 무난', 'Gold 4, steady', '金4、無難'],
          ['두 사람이 서로 눈치를 보며 일하니 크게 모자라지도 넘치지도 않았습니다.', 'With the two eyeing each other, results neither fell short nor soared.', '二人が互いに目を光らせて働き、不足も過剰もありませんでした。'],
          { fx: { gold: -4, food: 4 } })]),

    EV('c_hongmen', ['적국의 잔치 초대', 'An Invitation to the Enemy’s Banquet', '敵国の宴への招待'], '외교', 1.6, '일반',
      function (s) { return threat(s) >= 30; },
      ['긴장이 높은 이웃 나라가 화해를 핑계로 왕을 잔치에 초대했습니다. 옛 홍문연처럼 잔치가 암살의 자리가 될 수도, 큰 화해의 자리가 될 수도 있습니다.',
        'A tense neighbor invites the king to a banquet under the pretext of reconciliation. As at the old Hongmen Feast, it could be the scene of an assassination or a grand reconciliation.',
        '緊張の高まる隣国が、和解を口実に王を宴に招待しました。昔の鴻門の会のように、宴が暗殺の場にも、大きな和解の場にもなり得ます。'],
      [C(['왕이 직접 가되 정예 호위를 데려간다', 'The king attends with elite guards', '王自ら赴くが精鋭の護衛を連れていく'],
        ['금 6, 도박: 성공하면 관계 ++', 'Gold 6, gamble: relations sharply up on success', '金6、賭け：成功なら関係大幅上昇'],
        null,
        { fx: { gold: -6 }, fn: R(0.6, { t: ['잔치는 무사히 끝났고 두 나라는 오랜 갈등을 풀기로 했습니다.', 'The banquet passed without incident and the two states agreed to ease their old feud.', '宴は無事に終わり、両国は長い対立を解くことにしました。'], rel: { silla: 10, goguryeo: 8 }, world: { 'silla.hostility': -10 }, realm: { royal: 2 } },
          { t: ['잔치에서 자객이 나타났으나 호위가 막아 냈습니다. 상대는 모른 척했으나 관계는 크게 틀어졌습니다.', 'An assassin appeared at the banquet but the guards stopped him. The host feigned ignorance and relations soured greatly.', '宴で刺客が現れましたが護衛が防ぎました。相手は知らぬふりをしましたが、関係は大きくこじれました。'], rel: { silla: -12, goguryeo: -10 }, world: { 'silla.hostility': 8 }, fx: { morale: 3 } }) }),
        C(['믿을 만한 대신을 대신 보낸다', 'Send a trusted minister in the king’s place', '信頼できる大臣を代わりに送る'],
          ['금 4, 안전', 'Gold 4, safe', '金4、安全'],
          ['대신이 무난히 잔치에 참석하고 돌아왔습니다. 성과는 작지만 위험은 없었습니다.', 'The minister attended the banquet without trouble. The gains were small but there was no risk.', '大臣は無難に宴に出て戻りました。成果は小さいものの、危険はありませんでした。'],
          { fx: { gold: -4 }, rel: { silla: 3, goguryeo: 3 } }),
        C(['병을 핑계로 정중히 거절한다', 'Decline politely, pleading illness', '病を口実に丁重に断る'],
          ['관계 −', 'Relations down', '関係低下'],
          ['상대는 불쾌해했으나 구실이 있어 큰 문제는 되지 않았습니다.', 'The host was displeased but with a pretext it grew into no big problem.', '相手は不快がりましたが、口実があったので大きな問題にはなりませんでした。'],
          { rel: { silla: -3, goguryeo: -3 } })]),

    EV('c_price', ['곡식값을 다스리는 법', 'Taming the Price of Grain', '穀価を治める法'], '내정', 1.8, '일반', null,
      ['풍년에는 곡식값이 폭락해 농민이 울고, 흉년에는 폭등해 도시민이 굶주립니다. 옛 제나라 관중은 나라가 곡식을 사들이고 풀어 값을 안정시켰다고 합니다. 이 제도를 도입할지 논의가 벌어졌습니다.',
        'In good years grain prices crash and farmers weep, in bad years they soar and townspeople starve. Guan Zhong of old Qi stabilized prices by having the state buy and release grain. A debate is under way on adopting such a system.',
        '豊作の年は穀価が暴落して農民が泣き、凶作の年は高騰して都市の民が飢えます。昔の斉の管仲は、国が穀物を買い入れて放出し、価格を安定させたといいます。この制度を導入するか議論が起きました。'],
      [C(['관청이 곡식을 사고팔아 값을 안정시킨다', 'Have the state buy and sell grain to steady prices', '官が穀物を売買して価格を安定させる'],
        ['금 8, 산업·민심 +', 'Gold 8, economy and popular mood up', '金8、産業・民心上昇'],
        ['곡식값이 안정되자 농민과 도시민 모두 한숨을 돌렸습니다.', 'With grain prices steadied, both farmers and townspeople breathed easier.', '穀価が安定すると、農民も都市の民もほっとしました。'],
        { fx: { gold: -8, people: 3, food: 4 }, realm: { econ: 4 } }),
        C(['상인에게 맡기고 세만 거둔다', 'Leave it to merchants and just tax', '商人に任せ税だけ取る'],
          ['금 +4', 'Gold +4', '金+4'],
          ['시장은 제 흐름대로 움직였습니다. 투기꾼이 이득을 보았습니다.', 'The market moved on its own and speculators profited.', '市場は流れのままに動きました。投機家が儲けました。'],
          { fx: { gold: 4, people: -2 } }),
        C(['매점매석하는 상인만 엄히 단속한다', 'Crack down only on hoarders', '買い占めをする商人だけ厳しく取り締まる'],
          ['금 2, 민심 +', 'Gold 2, popular mood up', '金2、民心上昇'],
          ['몇몇 상인이 끌려가자 곡식값이 조금 내렸습니다.', 'A few merchants were hauled in and grain prices fell a little.', '数人の商人が連行されると、穀価が少し下がりました。'],
          { fx: { gold: -2, people: 2 } })]),

    EV('c_flood', ['큰물이 강둑을 넘다', 'The Great Flood', '大水が堤を越える'], '민생', 1.8, '일반', null,
      ['장마가 길어져 큰 강이 둑을 넘었습니다. 논밭이 잠기고 마을이 쓸려 갑니다. 백성을 구하는 일이 급하지만, 제방을 근본적으로 고쳐야 다음 홍수를 막을 수 있습니다.',
        'The long rains have pushed the great river over its banks. Fields are drowned and villages swept away. Rescuing the people is urgent, but the dikes must be fundamentally rebuilt to stop the next flood.',
        '長雨で大河が堤を越えました。田畑は水没し、村々が流されていきます。民の救出が急務ですが、次の洪水を防ぐには堤防を根本から直さねばなりません。'],
      [C(['구휼과 함께 제방을 새로 쌓는다', 'Provide relief and rebuild the dikes', '救済とともに堤防を新たに築く'],
        ['금 12, 군량 −5, 민심 +, 산업 +', 'Gold 12, food −5, popular mood and economy up', '金12、兵糧−5、民心・産業上昇'],
        ['피해는 컸으나 왕이 직접 나서 제방을 쌓자 백성들이 힘을 모았습니다.', 'The damage was great, but when the king stepped in to rebuild the dikes the people joined hands.', '被害は大きかったものの、王が自ら堤防を築くと民は力を合わせました。'],
        { fx: { gold: -12, food: -5, people: 4 }, realm: { econ: 3, defense: 1 } }),
        C(['급한 구휼만 하고 제방은 미룬다', 'Only urgent relief; postpone the dikes', '急ぎの救済だけして堤防は後回しにする'],
          ['금 5, 군량 −5', 'Gold 5, food −5', '金5、兵糧−5'],
          ['사람은 구했으나 제방은 그대로입니다. 내년이 걱정입니다.', 'Lives were saved but the dikes remain. Next year is a worry.', '人は救えましたが堤防はそのままです。来年が心配です。'],
          { fx: { gold: -5, food: -5, people: 2 } }),
        C(['피해 지역의 세금을 면제한다', 'Waive taxes in the damaged districts', '被災地の税を免除する'],
          ['금 −8, 민심 +', 'Gold −8, popular mood up', '金−8、民心上昇'],
          ['세금이 면제되자 백성들은 한숨을 돌렸습니다.', 'With taxes waived, the people breathed a sigh of relief.', '税が免除されると、民は一息つきました。'],
          { fx: { gold: -8, people: 5 } })]),

    EV('c_shaman', ['신통한 무당의 영향력', 'A Shaman’s Growing Influence', '霊験あらたかな巫女の影響力'], '정치', 1.4, '일반',
      function (s) { return s.realm.royal < 65; },
      ['신통하다는 무당이 도성 귀족 부인들을 사로잡고 조정 일에까지 입김을 넣기 시작했습니다. 그가 하늘의 뜻이라며 인사와 정책에 간섭하니 신하들이 불안해합니다.',
        'A shaman said to be gifted has captivated noble ladies in the capital and begun to breathe on court affairs. Invoking heaven’s will, they interfere in appointments and policy, and the ministers grow uneasy.',
        '霊験あらたかと評判の巫女が都の貴族の夫人たちを虜にし、朝廷の事にまで口を出し始めました。天の意志と称して人事や政策に干渉するため、臣下たちは不安になっています。'],
      [C(['궁에서 내쫓고 제사는 관청이 맡게 한다', 'Expel the shaman and let the state run the rites', '宮から追い出し、祭祀は官が担う'],
        ['왕권 +, 민심 −', 'Authority up, popular mood down', '王権上昇、民心低下'],
        ['무당이 떠나자 조정이 한결 조용해졌습니다. 그를 따르던 이들은 서운해했습니다.', 'With the shaman gone the court quieted down. Those who followed them were hurt.', '巫女が去ると朝廷は静かになりました。彼女を慕っていた者たちは残念がりました。'],
        { realm: { royal: 3 }, fx: { people: -2 } }),
        C(['제사 일에만 두고 정사 개입은 막는다', 'Keep them to rites and bar political meddling', '祭祀だけに留め、政治への介入は封じる'],
          ['금 2, 무난', 'Gold 2, steady', '金2、無難'],
          ['무당은 제사에만 힘쓰게 되었고 소란은 가라앉았습니다.', 'The shaman focused on rites alone and the stir subsided.', '巫女は祭祀に専念するようになり、騒ぎは収まりました。'],
          { fx: { gold: -2, people: 1 } }),
        C(['무당의 말을 따라 중요한 일을 결정한다', 'Follow the shaman’s words on key decisions', '巫女の言葉に従い重要事を決める'],
          ['도박: 길흉이 극단적', 'Gamble: extreme good or ill', '賭け：吉凶が極端'],
          null,
          { fn: R(0.4, { t: ['우연히 예언이 맞아떨어져 왕의 결정이 큰 성공을 거두었습니다.', 'By chance the prophecy came true and the king’s decision was a great success.', '偶然予言が当たり、王の決定は大成功を収めました。'], fx: { morale: 4, gold: 6 }, realm: { royal: 1 } },
            { t: ['예언이 틀려 큰 손해가 났고 신하들의 신뢰가 무너졌습니다.', 'The prophecy was wrong, causing heavy loss and shattering the ministers’ trust.', '予言が外れて大損害が出て、臣下たちの信頼が崩れました。'], fx: { gold: -8, morale: -3 }, realm: { royal: -5 } }) })]),

    EV('c_spy_caught', ['적의 첩자를 붙잡다', 'An Enemy Spy Is Caught', '敵の間者を捕らえる'], '첩보', 2, '일반',
      function (s) { return s.realm.intel >= 25; },
      ['경비병이 성문 근처에서 수상한 장사꾼을 붙잡았습니다. 심문해 보니 적국의 첩자였습니다. 그를 처형할지, 역이용해 거짓 정보를 흘릴지 정해야 합니다.',
        'Guards seized a suspicious peddler near the gate. Under questioning he turned out to be an enemy spy. We must decide whether to execute him or turn him to feed false information.',
        '衛兵が城門の近くで怪しい行商人を捕らえました。尋問すると敵国の間者でした。処刑するか、利用して偽情報を流すか決めねばなりません。'],
      [C(['처형해 본보기로 삼는다', 'Execute him as a warning', '処刑して見せしめにする'],
        ['왕권 +, 첩보 +', 'Authority and intelligence up', '王権・諜報上昇'],
        ['본보기가 서자 낯선 이들의 출입이 눈에 띄게 줄었습니다.', 'With the example set, strangers’ comings and goings dropped noticeably.', '見せしめが立つと、見知らぬ者の出入りが目に見えて減りました。'],
        { realm: { royal: 2, intel: 2 }, fx: { morale: 1 } }),
        C(['이중간첩으로 만들어 거짓 정보를 흘린다', 'Turn him into a double agent feeding false data', '二重間者にして偽情報を流す'],
          ['도박: 성공하면 적에게 타격', 'Gamble: a blow to the enemy on success', '賭け：成功なら敵に打撃'],
          null,
          { fn: R(0.55, { t: ['첩자는 우리 말대로 거짓 정보를 보냈고 적은 엉뚱한 곳에 군을 모았습니다.', 'The spy sent the false information as told and the enemy massed troops in the wrong place.', '間者は指示どおり偽情報を送り、敵は見当違いの場所に軍を集めました。'], world: { 'silla.p': -3 }, realm: { intel: 3 }, fx: { morale: 2 } },
            { t: ['첩자는 곧 적에게 정체를 알렸고 거꾸로 우리가 속았습니다.', 'The spy soon tipped off his masters and it was we who were fooled.', '間者はすぐ敵に正体を知らせ、かえってこちらが騙されました。'], realm: { intel: -3 }, fx: { morale: -2 } }) }),
        C(['풀어 주며 호의를 보인다', 'Release him as a gesture of goodwill', '放免して好意を示す'],
          ['관계 +', 'Relations up', '関係上昇'],
          ['풀려난 첩자가 돌아가 우리의 관대함을 전했다고 합니다.', 'The released spy is said to have carried word of our generosity home.', '放たれた間者は帰って、こちらの寛大さを伝えたといいます。'],
          { rel: { silla: 3, goguryeo: 2 }, world: { 'silla.hostility': -2 } })]),

    EV('c_stable', ['나라 목장의 확장', 'Expanding the Royal Pastures', '国営牧場の拡張'], '군사', 1.6, '일반',
      function (s) { return s.res.gold >= 15; },
      ['북방에서 사들이는 말값이 해마다 오르고 있습니다. 나라가 직접 큰 목장을 열어 말을 기르면 기병을 늘릴 수 있지만, 초지를 차지하려면 농민과 부딪힙니다.',
        'The price of horses bought from the north rises every year. If the state opens large pastures and breeds its own horses it can grow its cavalry, but taking grassland brings clashes with farmers.',
        '北方から買う馬の値が年々上がっています。国が大きな牧場を開いて馬を育てれば騎兵を増やせますが、草地を占めるには農民とぶつかります。'],
      [C(['변경에 큰 목장을 연다', 'Open large pastures on the frontier', '国境に大牧場を開く'],
        ['금 10, 기병 +', 'Gold 10, cavalry up', '金10、騎兵増加'],
        ['넓은 초지에 말이 늘어 기병이 한결 튼튼해졌습니다.', 'Horses multiplied on the wide grass and the cavalry grew stouter.', '広い草地で馬が増え、騎兵は一層頼もしくなりました。'],
        { fx: { gold: -10 }, army: { baekje_horse: 400 }, realm: { train: 1 } }),
        C(['민간 목장을 지원하고 말을 사들인다', 'Support private ranches and buy their horses', '民間牧場を支援して馬を買い入れる'],
          ['금 6, 기병 소폭 +', 'Gold 6, cavalry up slightly', '金6、騎兵小幅増加'],
          ['농가와 마찰 없이 말이 조금씩 늘었습니다.', 'Horses increased bit by bit without friction with the farms.', '農家との摩擦なく馬が少しずつ増えました。'],
          { fx: { gold: -6, people: 1 }, army: { baekje_horse: 200 } }),
        C(['농지가 더 급하다며 접는다', 'Drop it; farmland is more pressing', '農地の方が急務だとして見送る'],
          ['변화 없음', 'No change', '変化なし'],
          ['말은 계속 비싸게 사들일 수밖에 없습니다.', 'Horses will have to keep being bought at high prices.', '馬はこれからも高く買い続けるしかありません。'], {})]),
  ];

  /* 위 선택지에서 함수 안에서 쓰는 결과 문장은 파일을 읽을 때 한 번만 번역 등록한다 */
  var USAN_OK, USAN_NG, SALSU_OK, SALSU_NG, SALSU_FRONT_OK, SALSU_FRONT_NG, BAESU_OK, BAESU_NG;
  USAN_OK = T('수군이 상륙해 섬을 제압하자 섬의 우두머리가 무릎을 꿇었습니다.', 'The navy landed and overran the island and its chieftain knelt.', '水軍が上陸して島を制圧すると、島の首長がひざまずきました。');
  USAN_NG = T('거친 파도에 배 여러 척이 부서지고 상륙은 실패했습니다.', 'Rough waves smashed several ships and the landing failed.', '荒波で船が何隻も砕け、上陸は失敗しました。');
  SALSU_OK = T('적이 강을 건너는 순간 복병이 일제히 들고일어나 대군을 물리쳤습니다.', 'As the enemy crossed the river our hidden troops rose together and routed the great army.', '敵が川を渡る瞬間、伏兵が一斉に起こり、大軍を撃ち破りました。');
  SALSU_NG = T('적은 유인책을 눈치채고 강을 건너지 않았으며 오히려 우리 복병이 들통났습니다.', 'The enemy saw through the lure, never crossed the river, and discovered our hidden troops.', '敵は誘いを見抜いて川を渡らず、かえってこちらの伏兵が露見しました。');
  SALSU_FRONT_OK = T('훈련된 군이 정면에서 버텨 적의 선봉을 꺾었습니다. 피해도 적지 않았습니다.', 'Our trained army held firm head-on and broke the enemy vanguard, though losses were not small.', '訓練された軍が正面で踏みとどまり、敵の先鋒を砕きました。損害も少なくありませんでした。');
  SALSU_FRONT_NG = T('수가 너무 많은 적에게 정면으로 맞서 크게 패했습니다.', 'Meeting a far larger enemy head-on, we were badly defeated.', '数の多すぎる敵に正面から挑み、大敗しました。');
  BAESU_OK = T('퇴로가 없자 병사들은 죽을힘을 다해 싸웠고 적은 무너졌습니다.', 'With no retreat open the soldiers fought with desperate strength and the enemy collapsed.', '退路がないため、兵たちは死力を尽くして戦い、敵は崩れました。');
  BAESU_NG = T('병사들이 공포에 질려 강으로 몰렸고 크게 무너졌습니다.', 'Terrified, the soldiers were driven into the river and collapsed.', '兵たちは恐怖に駆られて川へ追い込まれ、大きく崩れました。');
  E = E.filter(Boolean);
  SG.data.events = (SG.data.events || []).concat(E);
})();

