    $('#wf-r', card).oninput = function () { $('#wf-v', card).textContent = this.value + '%'; upd(); }; upd();
    $('#wf-x', card).onclick = function () { wrap.remove(); s.last = '출병을 거두었습니다. (행동력은 쓰이지 않았습니다)'; self.renderTurn(); };
    wrap.appendChild(card); g.root.appendChild(wrap);
