  /* ── ② 화면 번역 ── */
  function trText(n) { var s = n.nodeValue; if (!s || !KO.test(s)) return; var r = I.t(s); if (r !== s) n.nodeValue = r; }
  var ATTR = ['title', 'placeholder', 'aria-label', 'alt'];
