      var b = document.createElement('button'); b.type = 'button'; b.textContent = l[1]; b.lang = l[0]; b.setAttribute('translate', 'no');
      var on = l[0] === I.lang; if (on) b.className = 'on'; b.setAttribute('aria-pressed', on ? 'true' : 'false');
